  "scenario_id": "sc-5e376b",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [2020, 2022],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.35 to +0.40 A/E",
      "confidence": 0.95,
      "evidence": [
        "ae_death_by_year.csv shows A/E climbing from 0.876 (2019) to 1.235 (2020), 1.254 (2021), and 1.308 (2022) before reverting to 0.856 (2023).",
        "Year-on-year rise and deviations of +0.35 to +0.40 are 5-10x the expected Poisson noise (~0.04-0.07), confirming a sustained level shift rather than random volatility."
      ],
      "recommended_action": "Investigate mortality drivers during 2020-2022 (e.g., pandemic impact, underwriting or claims adjudication changes). Review pricing and valuation assumptions for this period and assess tail claim development and reserve adequacy."
    }
  ]
}

